import { Block, Text } from "@prototyp/skeletor";
import { useIsFocused } from "@react-navigation/native";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import {
  MembershipState_Tags,
  PowerLevel_Tags,
  type RoomMember,
} from "@unomed/react-native-matrix-sdk";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
import { NavigationContainerRef } from "modules/navigation/const";
import { RoomService } from "modules/room/service/RoomService";
import { useCallback, useEffect, useMemo, useState } from "react";
import { Image, SectionList, StyleSheet } from "react-native";
import { Button, Loading, MemberDetailsBottomSheet } from "shared/components";
import { GoBackHeader } from "shared/components/go-back-header/GoBackHeader";
import { ScreenLayout } from "shared/components/screen-layout/ScreenLayout";
import { UserImage } from "shared/components/user-image/UserImage";
import { useMemberDetails } from "shared/hooks";
import { Colors, TextSize } from "shared/styles";
import { getLevelLabel } from "shared/utils";

export const RoomMembers: React.FC<
  NativeStackScreenProps<Routes, "roomMembers">
> = ({ route }) => {
  const { members: initialMembers, roomId } = route.params;
  const [members, setMembers] = useState<RoomMember[]>(initialMembers);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [canInvite, setCanInvite] = useState(false);
  const isFocused = useIsFocused();
  const {
    selectedMember,
    isBottomSheetOpen,
    openMemberDetails,
    closeMemberDetails,
  } = useMemberDetails();

  const pendingMembers = useMemo(
    () =>
      members.filter(
        (member) => member.membership?.tag === MembershipState_Tags.Invite,
      ),
    [members],
  );
  const acceptedMembers = useMemo(
    () =>
      members.filter(
        (member) => member.membership?.tag === MembershipState_Tags.Join,
      ),
    [members],
  );
  const bannedMembers = useMemo(
    () =>
      members.filter(
        (member) => member.membership?.tag === MembershipState_Tags.Ban,
      ),
    [members],
  );

  const sections = useMemo(
    () => [
      {
        title: "Pending",
        data: pendingMembers,
      },
      {
        title: "",
        data: acceptedMembers,
      },
      {
        title: "Banned",
        data: bannedMembers,
      },
    ],
    [pendingMembers, acceptedMembers, bannedMembers],
  );

  const refreshMembers = useCallback(async () => {
    setIsRefreshing(true);
    try {
      const room = RoomService.getRoomInfo(roomId);
      if (!room) return;

      const membersInfo = await room.members();
      const membersList = membersInfo.nextChunk(100000) ?? [];
      setMembers(membersList);
    } catch (error) {
      console.error("Failed to refresh members:", error);
    } finally {
      setIsRefreshing(false);
    }
  }, [roomId]);

  const handleMemberAction = useCallback(
    (userId: string, action: "remove" | "ban" | "unban") => {
      setMembers((currentMembers) => {
        return currentMembers.map((member) => {
          if (member.userId !== userId) return member;

          const newMembershipTag =
            action === "ban"
              ? MembershipState_Tags.Ban
              : MembershipState_Tags.Leave; // For unban and remove, we change the membership to leave

          return {
            ...member,
            membership: {
              ...member.membership,
              tag: newMembershipTag,
            },
          };
        });
      });

      setTimeout(() => {
        refreshMembers();
      }, 2000);
    },
    [refreshMembers],
  );

  const handleMemberPress = useCallback(
    (member: RoomMember) => {
      openMemberDetails({
        userId: member.userId,
        displayName: member.displayName ?? "Unknown",
        avatarUrl: member.avatarUrl ?? null,
        membershipTag: member.membership?.tag,
      });
    },
    [openMemberDetails],
  );

  useEffect(() => {
    if (!isFocused) return;
    refreshMembers();
  }, [isFocused, refreshMembers]);

  useEffect(() => {
    const checkInvitePermission = async () => {
      const myUserId = MatrixCore.instance?.userId();
      if (!myUserId) return;

      const powerLevels = await RoomService.getRoomPowerLevels(roomId);
      if (!powerLevels) return;

      const inviteLevel = Number(powerLevels.values().invite);
      const myLevel = Number(powerLevels.userPowerLevels().get(myUserId) ?? 0);
      setCanInvite(myLevel >= inviteLevel);
    };

    checkInvitePermission().catch(console.error);
  }, [roomId]);

  return (
    <ScreenLayout type="modal">
      {isRefreshing && <Loading text="Refreshing members..." />}
      <Block align="center" width="100%">
        <GoBackHeader
          title="Members"
          margins={0}
          rightComp={
            canInvite && (
              <Button.Wrapper
                onPress={() =>
                  NavigationContainerRef.navigate("invitePeople", {
                    roomId,
                    members,
                  })
                }
              >
                <Image
                  source={require("assets/icons/plus.png")}
                  tintColor={Colors.white}
                  width={24}
                  height={24}
                />
              </Button.Wrapper>
            )
          }
        />
        <Text size={TextSize.tiny} color={Colors.white80}>
          {acceptedMembers.length}{" "}
          {acceptedMembers.length === 1 ? "member" : " members"}
        </Text>
        <SectionList
          sections={sections}
          style={styles.container}
          contentContainerStyle={styles.contentContainer}
          renderItem={({ item }) => (
            <Button.Wrapper onPress={() => handleMemberPress(item)}>
              <Block
                width="100%"
                flexDirection="row"
                align="center"
                justify="space-between"
                gap={12}
              >
                <Block flexDirection="row" align="center" gap={12} flex={1}>
                  <UserImage
                    avatarUrl={item.avatarUrl}
                    displayName={item.displayName}
                    width={40}
                    height={40}
                  />
                  <Block flex={1}>
                    <Text numberOfLines={1}>{item.displayName}</Text>
                    <Text
                      numberOfLines={1}
                      size={TextSize.tiny}
                      color={Colors.white50}
                    >
                      {item.userId}
                    </Text>
                  </Block>
                </Block>
                {item.powerLevel.tag === PowerLevel_Tags.Value &&
                  getLevelLabel(Number(item.powerLevel.inner.value)) !==
                    "Member" && (
                    <Block>
                      <Text color={Colors.white50}>
                        {getLevelLabel(Number(item.powerLevel.inner.value))}
                      </Text>
                    </Block>
                  )}
              </Block>
            </Button.Wrapper>
          )}
          renderSectionHeader={({ section }) => {
            if (!section.data.length) return null;

            return (
              <Block>
                <Text size={TextSize.tiny} color={Colors.white80}>
                  {section.title === ""
                    ? `${section.data.length} ${section.data.length === 1 ? "member" : "members"}`
                    : section.title}
                </Text>
              </Block>
            );
          }}
        />
      </Block>
      <MemberDetailsBottomSheet
        isBottomSheetOpen={isBottomSheetOpen}
        selectedMember={selectedMember}
        roomId={roomId}
        onClose={closeMemberDetails}
        onMemberAction={handleMemberAction}
      />
    </ScreenLayout>
  );
};

const styles = StyleSheet.create({
  container: {
    width: "100%",
    gap: 12,
    marginTop: 36,
    padding: 0,
  },
  contentContainer: {
    width: "100%",
    gap: 12,
  },
});

