    18→  avatarUrl,
    19→  displayName,
    20→  height = 32,
    21→  width = 32,
    22→  borderRadius = 48,
    23→}) => {
    24→  const [uri, setUri] = useState<string | null>(null);
    25→  const textSize = () => {
    26→    if (height < 20) return TextSize.xtiny;
    27→    if (height < 28) return TextSize.tiny;
    28→    if (height < 32) return TextSize.small;
    29→    if (height < 40) return TextSize.base;
    30→    if (height < 48) return TextSize.medium;
    31→    if (height < 56) return TextSize.large;
    32→
    33→    return TextSize.xlarge;
    34→  };
    35→
    36→  useEffect(() => {
    37→    const fetch = async () => {
    38→      if (!avatarUrl) {
    39→        setUri(null);
    40→        return;
    41→      }
    42→
    43→      try {
    44→        const url = await fetchMedia({
    45→          url: avatarUrl,
    46→          width,
    47→          height,
    48→          serverUrl:
    49→            MatrixCore.instance?.session().homeserverUrl || MatrixBaseURL,
    50→        });
    51→        setUri(url);
    52→      } catch (e) {
    53→        console.log(e);
    54→      }
    55→    };
    56→
    57→    fetch();
    58→  }, [avatarUrl, width, height]);
    59→
    60→  if (uri) {
    61→    return (
    62→      <Image
    63→        source={{ uri }}
    64→        width={width}
    65→        height={height}
    66→        style={{
    67→          width,
