import { animateParallel, Block, Text } from "@prototyp/skeletor";
import { useAtom } from "jotai";
import { RoomService } from "modules/room/service/RoomService";
import { TimelineAtoms } from "modules/timeline/jotai";
import { TimelineService } from "modules/timeline/service/TimelineService";
import { type FC, useEffect, useRef, useState } from "react";
import { Image, type NativeSyntheticEvent, type TextInputSelectionChangeEventData } from "react-native";
import { Button, Input } from "shared/components";
import { Colors } from "shared/styles";
import { InputMessagePayload } from "../input-message-payload";
import { MentionSuggestionList, type MentionItem } from "../mention-suggestion-list";
import { SendItemsList } from "../send-items-list";
import { VoiceRecordButton } from "../voice-record-button";

interface Props {
  roomId: string;
}

const sendButtonTransition = animateParallel(
  { opacity: [0, 1], width: [0, 56] },
  { duration: 200, native: false },
);

const imageTransition = animateParallel(
  { opacity: [0, 1], width: [0, 48] },
  { duration: 200, native: false },
);

const inputTransition = animateParallel(
  { opacity: [0, 1], width: ["0%", "100%"] },
  { duration: 200, native: false },
);

const findMentionTrigger = (
  text: string,
  cursorPos: number,
): { start: number; query: string } | null => {
  for (let i = cursorPos - 1; i >= 0; i--) {
    const char = text[i];
    if (char === "@") {
      return { start: i, query: text.slice(i + 1, cursorPos) };
    }
    if (char === " " || char === "\n") return null;
  }
  return null;
};

export const RoomInput: FC<Props> = ({ roomId }) => {
  const [message, setMessage] = useState("");
  const [isRecording, setIsRecording] = useState(false);
  const [isRecorded, setIsRecorded] = useState(false);
  const [canSend, setCanSend] = useState(true);
  const [mentionQuery, setMentionQuery] = useState<string | null>(null);
  const [mentionStart, setMentionStart] = useState(-1);
  const [mentions, setMentions] = useState<Map<string, string>>(new Map()); // displayName -> userId
  const cursorRef = useRef(0);

  useEffect(() => {
    Promise.all([
      RoomService.getUserPowerLevel(roomId),
      RoomService.getRoomPowerLevels(roomId),
    ])
      .then(([userLevel, pl]) => {
        const sendLevel = pl ? Number(pl.values().eventsDefault) : 0;
        setCanSend((userLevel ?? 0) >= sendLevel);
      })
      .catch(console.error);
  }, [roomId]);
  const [replyPayload, setReplyPayload] = useAtom(TimelineAtoms.replyPayload);
  const [editPayload, setEditPayload] = useAtom(TimelineAtoms.editPayload);
  const hasPayload = !!replyPayload || !!editPayload;

  const handleTextChange = (text: string) => {
    setMessage(text);
    const trigger = findMentionTrigger(text, cursorRef.current);
    if (trigger) {
      setMentionQuery(trigger.query);
      setMentionStart(trigger.start);
    } else {
      setMentionQuery(null);
      setMentionStart(-1);
    }
  };

  const handleSelectionChange = (
    e: NativeSyntheticEvent<TextInputSelectionChangeEventData>,
  ) => {
    const cursor = e.nativeEvent.selection.start;
    cursorRef.current = cursor;
    const trigger = findMentionTrigger(message, cursor);
    if (trigger) {
      setMentionQuery(trigger.query);
      setMentionStart(trigger.start);
    } else {
      setMentionQuery(null);
      setMentionStart(-1);
    }
  };

  const handleMentionSelect = (item: MentionItem) => {
    const before = message.slice(0, mentionStart);
    const after = message.slice(mentionStart + 1 + (mentionQuery?.length ?? 0));
    const newText = `${before}@${item.displayName} ${after}`;
    setMessage(newText);
    setMentionQuery(null);
    setMentionStart(-1);
    setMentions((prev) => {
      const next = new Map(prev);
      next.set(item.displayName, item.userId);
      return next;
    });
  };

  const handleSendMessage = async () => {
    if (!message) return;

    const mentionUserIds = Array.from(mentions.values());
    const messageMentions =
      mentionUserIds.length > 0
        ? { userIds: mentionUserIds, room: false }
        : undefined;

    try {
      if (editPayload) {
        await TimelineService.editMessage(
          roomId,
          editPayload.event,
          message,
          messageMentions,
        );
        setEditPayload(null);
        return;
      }

      if (replyPayload) {
        await TimelineService.replyToMessage(
          roomId,
          message,
          replyPayload.eventId,
          messageMentions,
        );
        setReplyPayload(null);
        return;
      }

      await TimelineService.sendMessage(roomId, message, messageMentions);
    } catch (error) {
      console.error("Failed to send message:", error);
    } finally {
      setMessage("");
      setMentions(new Map());
    }
  };

  useEffect(() => {
    if (!editPayload) {
      setMessage("");
      return;
    }
    setMessage(editPayload.content);
  }, [editPayload]);

  useEffect(() => {
    if (message || replyPayload) {
      sendButtonTransition.start();
      imageTransition.reverse();
    } else {
      sendButtonTransition.reverse();
      imageTransition.start();
    }
  }, [message, replyPayload]);

  useEffect(() => {
    setReplyPayload(null);
    setEditPayload(null);
  }, [setEditPayload, setReplyPayload]);

  useEffect(() => {
    if (isRecording || isRecorded) {
      imageTransition.reverse();
      inputTransition.reverse();
    } else {
      imageTransition.start();
      inputTransition.start();
    }
  }, [isRecording, isRecorded]);

  if (!canSend) {
    return (
      <Block paddings={20} flexDirection="row" align="center" gap={8}>
        <Image
          source={require("assets/icons/warning.png")}
          width={24}
          height={24}
          tintColor={Colors.white80}
        />
        <Text color={Colors.white80}>
          You don't have permission to send messages
        </Text>
      </Block>
    );
  }

  return (
    <Block>
      {mentionQuery !== null && (
        <MentionSuggestionList
          roomId={roomId}
          query={mentionQuery}
          onSelect={handleMentionSelect}
        />
      )}
      <Block
        paddings={[20, 0, 20, 16]}
        flexDirection="row"
        align="flex-end"
        justify="space-between"
        height={hasPayload ? 158 : 88}
        gap={message || replyPayload ? 0 : 8}
      >
        <Block
          animations={imageTransition.animations}
          height={48}
          align="center"
          justify="center"
        >
          <SendItemsList roomId={roomId} />
        </Block>
        <VoiceRecordButton
          roomId={roomId}
          message={message}
          isRecording={isRecording}
          isRecorded={isRecorded}
          setIsRecorded={setIsRecorded}
          setIsRecording={setIsRecording}
        />
        <Block
          flex={isRecording || isRecorded ? 0 : 1}
          animations={inputTransition.animations}
          border={{ borderRadius: hasPayload ? 12 : 40 }}
          background={Colors.white5}
        >
          <InputMessagePayload />
          <Input
            placeholder="Message"
            value={message}
            background="transparent"
            autoCapitalize="none"
            onChangeText={handleTextChange}
            onSelectionChange={handleSelectionChange}
          />
        </Block>
        <Block
          animations={sendButtonTransition.animations}
          height={48}
          overflow="hidden"
        >
          <Button.Wrapper disabled={!message} onPress={handleSendMessage}>
            <Block
              height={48}
              width={48}
              align="center"
              justify="center"
              background={Colors.primary}
              border={{
                borderRadius: 24,
              }}
              margins={{ marginLeft: 8 }}
            >
              <Image
                source={require("assets/icons/paper-plane-right.png")}
                width={24}
                height={24}
              />
            </Block>
          </Button.Wrapper>
        </Block>
      </Block>
    </Block>
  );
};

