      mediaSource,
    };
  }, [event]);

  const handleReplyPress = useCallback(() => {
    if (replyPayload) setScrollToEventId(replyPayload.eventId);
  }, [replyPayload, setScrollToEventId]);

  useEffect(() => {
    TimelineService.getReadReceipts(event)
      .then(setSeenBy)
      .catch((error) => {
        console.error("Failed to get read receipt users:", error);
        setSeenBy([]);
      });
  }, [event]);

  return (
    <Block
      align={isUser ? "flex-end" : "flex-start"}
      margins={{ marginTop: isPreviousSameSender ? 6 : 16 }}
    >
      <MessageSender
        sender={sender}
        senderId={senderId}
        isUser={isUser}
        isPreviousSameSender={isPreviousSameSender}
        onMemberPress={onMemberPress}
      />
      <MessageLongPressWrapper event={event} content={content}>
        <Block flexDirection={isUser ? "row-reverse" : "row"}>
          <Block
            paddings={12}
            background={isUser ? Colors.primary : Colors.message}
            border={{ borderRadius: 24 }}
            align="stretch"
            gap={12}
            onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
            maxWidth={maxWidth}
          >
            <ReplyPayload
              replyPayload={replyPayload}
              onPress={handleReplyPress}
            />
            <Block
              justify="space-between"
              align="center"
              flex={{ flexWrap: "wrap" }}
              flexDirection={isUser ? "row-reverse" : "row"}
              gap={{
                row: 4,
                col: 16,
              }}
              // Some short strings (e.g., "aa", "ai") wrap unexpectedly, while others ("dd", "a") do not.
              // Add this value to prevent unwanted wrapping for short text.
              minWidth={90}
            >
              {mentionedProfiles.size > 0 ? (
                <RNText style={styles.messageText}>
                  {renderMentions(content, mentionedProfiles, onMemberPress)}
                </RNText>
              ) : (
                <Text size={TextSize.small} color="white">
                  {content}
                </Text>
              )}
              <MessageTimestamp event={event} isUser={isUser} />
            </Block>
            {isPreviousSameSender && (
              <Block
                absolute
                offsets={
                  isUser
                    ? {
                        right: 6,
                        bottom: 2,
                      }
                    : {
                        left: 6,
                        bottom: 2,
                      }
                }
              >
                <Image
                  source={
                    isUser
                      ? require("assets/icons/polygon.png")
                      : require("assets/icons/guest-polygon.png")
                  }
                  width={7}
                  height={6}
                  style={styles.polygon}
                />
              </Block>
            )}
          </Block>
          <PinIndicator event={event} />
        </Block>
      </MessageLongPressWrapper>
      <SeenBy seenBy={seenBy} messageWidth={messageWidth} />
    </Block>
  );
};

function renderMentions(
  body: string,
  profiles: Map<string, { displayName: string; avatarUrl: string | null }>,
  onMemberPress?: (member: MemberDetailsPayload) => void,
): React.ReactNode[] {
  const entries = Array.from(profiles.entries()).sort(
    (a, b) => b[1].displayName.length - a[1].displayName.length,
  );
  const displayNameToUserId = new Map(
    entries.map(([userId, p]) => [p.displayName.toLowerCase(), userId]),
  );
  const escapedNames = entries.map(([, p]) =>
    p.displayName.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"),
  );
  const pattern = new RegExp(`@(${escapedNames.join("|")})`, "gi");
  const parts = body.split(pattern);

  return parts.map((part, i) => {
    if (i % 2 === 1) {
      const userId = displayNameToUserId.get(part.toLowerCase());
      const profile = userId ? profiles.get(userId) : undefined;
      if (userId && profile) {
        return (
          <RNText
            key={i}
            style={styles.mention}
            onPress={() =>
              onMemberPress?.({
                userId,
                displayName: profile.displayName,
                avatarUrl: profile.avatarUrl,
              })
            }
          >
            {`@${part}`}
          </RNText>
        );
      }
    }
    return part;
  });
}

const styles = StyleSheet.create({
  polygon: {
    width: 7,
    height: 6,
  },
  messageText: {
    fontSize: TextSize.small[0],
    lineHeight: TextSize.small[1],
    color: Colors.white,
    fontFamily: "InstrumentSans-Regular",
  },
  mention: {
    color: Colors.primary,
    fontFamily: "InstrumentSans-Regular",
  },
});

