import type { FC } from "react";
import { StyleSheet, Text as RNText } from "react-native";
import { Colors, TextSize } from "shared/styles";

interface MentionProfile {
  displayName: string;
  avatarUrl: string | null;
}

interface Props {
  body: string;
  profiles: Map<string, MentionProfile>;
  onMentionPress?: (member: MemberDetailsPayload) => void;
}

export const MentionText: FC<Props> = ({ body, profiles, onMentionPress }) => {
  const entries = Array.from(profiles.entries()).sort(
    (a, b) => b[1].displayName.length - a[1].displayName.length,
  );
  const displayNameToUserId = new Map(
    entries.map(([userId, p]) => [p.displayName.toLowerCase(), userId]),
  );
  const escapedNames = entries.map(([, p]) =>
    p.displayName.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"),
  );
  const pattern = new RegExp(`@(${escapedNames.join("|")})`, "gi");
  const parts = body.split(pattern);

  return (
    <RNText style={styles.text}>
      {parts.map((part, i) => {
        if (i % 2 === 1) {
          const userId = displayNameToUserId.get(part.toLowerCase());
          const profile = userId ? profiles.get(userId) : undefined;
          if (userId && profile) {
            return (
              <RNText
                key={i}
                style={styles.mention}
                onPress={() =>
                  onMentionPress?.({
                    userId,
                    displayName: profile.displayName,
                    avatarUrl: profile.avatarUrl,
                  })
                }
              >
                {`@${part}`}
              </RNText>
            );
          }
        }
        return part;
      })}
    </RNText>
  );
};

const styles = StyleSheet.create({
  text: {
    fontSize: TextSize.small[0],
    lineHeight: TextSize.small[1],
    color: Colors.white,
    fontFamily: "InstrumentSans-Regular",
  },
  mention: {
    color: Colors.primary,
    fontFamily: "InstrumentSans-Regular",
  },
});

