// Build an HTML formatted_body where each @DisplayName becomes a matrix.to mention link.
// The plain-text body is kept as-is — messageEventContentFromHtml handles the split,
// matching the iOS SDK's messageEventContentFromHtml(body:htmlBody:) path.
const buildHtmlBodyWithMentions = (
  text: string,
  mentionMap: Map<string, string>, // displayName -> userId
): string | undefined => {
  if (!mentionMap.size) return undefined;
  // Sort longest name first to avoid partial replacements (e.g. "Alice" before "Ali")
  const sorted = Array.from(mentionMap.entries()).sort(
    (a, b) => b[0].length - a[0].length,
  );
  // Escape HTML special chars in the plain text before inserting tags
  let result = text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
  for (const [displayName, userId] of sorted) {
    const escapedName = displayName
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");
    const regexEscaped = escapedName.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    result = result.replace(
      new RegExp(`@${regexEscaped}`, "g"),
      `<a href="https://matrix.to/#/${userId}">@${escapedName}</a>`,
    );
  }
  return result;
};

