import { Block, Text } from "@prototyp/skeletor";
import {
  MembershipState_Tags,
  type RoomMember,
} from "@unomed/react-native-matrix-sdk";
import { RoomService } from "modules/room/service/RoomService";
import { type FC, useEffect, useMemo, useState } from "react";
import { FlatList } from "react-native";
import { Button } from "shared/components";
import { UserImage } from "shared/components/user-image/UserImage";
import { Colors, TextSize } from "shared/styles";

export interface MentionItem {
  userId: string;
  displayName: string;
  avatarUrl: string | null;
}

interface Props {
  roomId: string;
  query: string;
  onSelect: (item: MentionItem) => void;
}

export const MentionSuggestionList: FC<Props> = ({
  roomId,
  query,
  onSelect,
}) => {
  const [members, setMembers] = useState<MentionItem[]>([]);

  useEffect(() => {
    const fetch = async () => {
      const room = RoomService.getRoomInfo(roomId);
      if (!room) return;
      const membersInfo = await room.members();
      const list = membersInfo.nextChunk(100000) ?? [];
      const joined = list.filter(
        (m: RoomMember) => m.membership?.tag === MembershipState_Tags.Join,
      );
      setMembers(
        joined.map((m: RoomMember) => ({
          userId: m.userId,
          displayName: m.displayName ?? m.userId,
          avatarUrl: m.avatarUrl ?? null,
        })),
      );
    };
    fetch().catch(console.error);
  }, [roomId]);

  const filtered = useMemo(() => {
    const q = query.toLowerCase();
    return members.filter(
      (m) =>
        m.displayName.toLowerCase().includes(q) ||
        m.userId.toLowerCase().includes(q),
    );
  }, [members, query]);

  if (!filtered.length) return null;

  return (
    <Block
      background={Colors.blackMinus2}
      border={{ borderRadius: 12, borderWidth: 1, borderColor: Colors.white10 }}
      margins={{ marginHorizontal: 16, marginBottom: 4 }}
      style={{ maxHeight: 200, overflow: "hidden" }}
    >
      <FlatList
        data={filtered}
        keyExtractor={(item) => item.userId}
        keyboardShouldPersistTaps="always"
        renderItem={({ item }) => (
          <Button.Wrapper onPress={() => onSelect(item)}>
            <Block
              flexDirection="row"
              align="center"
              gap={10}
              paddings={[10, 14]}
            >
              <UserImage
                avatarUrl={item.avatarUrl}
                displayName={item.displayName}
                width={32}
                height={32}
              />
              <Block flex={1}>
                <Text numberOfLines={1}>{item.displayName}</Text>
                <Text
                  numberOfLines={1}
                  size={TextSize.tiny}
                  color={Colors.white50}
                >
                  {item.userId}
                </Text>
              </Block>
            </Block>
          </Button.Wrapper>
        )}
      />
    </Block>
  );
};
